import re


def sorted_names():
    return lambda num: float(re.search(r'\d+', num).group())


def sorted_names_LNCEL(dn_type):
    """

    :param dn_type:
    :return:
    """
    example_object = list(dn_type)[0]
    if re.search(r'LNCEL', example_object):
        regex = r'LNCEL-(\d+)'
        return lambda num: float(re.findall(regex, num)[0])
    elif re.search(r'NRCELL', example_object):
        regex = r'NRCELL-(\d+)'
        return lambda num: float(re.findall(regex, num)[0])
    else:
        return str.lower
